import {
  GenMapping,
  maybeAddMapping,
  setSourceContent,
  allMappings,
  toEncodedMap,
  toDecodedMap,
} from "@jridgewell/gen-mapping";

import type {
  EncodedSourceMap,
  DecodedSourceMap,
  Mapping,
} from "@jridgewell/gen-mapping";

import {
  type SourceMapInput,
  originalPositionFor,
  TraceMap,
} from "@jridgewell/trace-mapping";
import { isValidIdentifier } from "@babel/types";
import * as charCodes from "charcodes";

/**
 * Build a sourcemap.
 */

export default class SourceMap {
  private _map: GenMapping;
  private _rawMappings: Mapping[] | undefined;
  private _sourceFileName: string | undefined;

  // Any real line is > 0, so init to 0 is fine.
  private _lastGenLine = 0;
  private _lastSourceLine = 0;

  // Source columns can be 0, but we ony check in unison with sourceLine, which
  // inits to an impossible value. So init to 0 is fine.
  private _lastSourceColumn = 0;

  public _inputMap: TraceMap;

  constructor(
    opts: {
      sourceFileName?: string;
      sourceRoot?: string;
      inputSourceMap?: SourceMapInput;
    },
    code: string | { [sourceFileName: string]: string },
  ) {
    const map = (this._map = new GenMapping({ sourceRoot: opts.sourceRoot }));
    this._rawMappings = undefined;

    const slashChar = "/";
    const backslashCode = charCodes.backslash;
    const colonCode = charCodes.colon;
    const questionCode = charCodes.questionMark;
    const hashCode = charCodes.numberSign;
    const slashCode = charCodes.slash;
    const isPathSep: { [code: number]: boolean } = {};
    isPathSep[slashCode] = true;
    isPathSep[backslashCode] = true;
    const isSchemeStop: { [code: number]: boolean } = {};
    isSchemeStop[slashCode] = true;
    isSchemeStop[backslashCode] = true;
    isSchemeStop[questionCode] = true;
    isSchemeStop[hashCode] = true;
    isSchemeStop[colonCode] = true;
    const identifierLikeSources: { [name: string]: boolean } = {};
    const knownSchemes: { [scheme: string]: boolean } = {};
    knownSchemes.http = true;
    knownSchemes.https = true;
    knownSchemes.file = true;
    knownSchemes.ftp = true;
    knownSchemes.ftps = true;
    knownSchemes.ws = true;
    knownSchemes.wss = true;
    knownSchemes.data = true;
    knownSchemes.blob = true;
    knownSchemes.about = true;
    knownSchemes.mailto = true;
    knownSchemes.chrome = true;
    knownSchemes.webpack = true;
    knownSchemes.nodejs = true;
    knownSchemes.electron = true;
    knownSchemes.resource = true;
    knownSchemes.assets = true;
    knownSchemes.gopher = true;
    knownSchemes.nntp = true;
    knownSchemes.news = true;
    knownSchemes.imap = true;
    knownSchemes.smtp = true;
    knownSchemes.ssh = true;
    knownSchemes.git = true;
    knownSchemes.svn = true;
    knownSchemes.hg = true;
    knownSchemes.jar = true;
    knownSchemes.zip = true;
    knownSchemes.vscode = true;
    knownSchemes.view = true;
    knownSchemes.source = true;

    const rawSourceFileName = opts.sourceFileName;
    if (rawSourceFileName == null) {
      this._sourceFileName = undefined;
    } else if (rawSourceFileName.length === 0) {
      this._sourceFileName = "";
    } else if (isValidIdentifier(rawSourceFileName, false)) {
      this._sourceFileName = rawSourceFileName;
      identifierLikeSources[rawSourceFileName] = true;
    } else {
      let converted = "";
      const sourceLength = rawSourceFileName.length;
      let cursor = 0;
      const firstCode = rawSourceFileName.charCodeAt(0);

      if (isPathSep[firstCode]) {
        if (sourceLength > 1) {
          const secondCode = rawSourceFileName.charCodeAt(1);
          if (isPathSep[secondCode]) {
            converted += "//";
            cursor = 2;
            while (cursor < sourceLength) {
              const codePoint = rawSourceFileName.charCodeAt(cursor);
              if (codePoint === backslashCode) {
                converted += "/";
                cursor++;
                break;
              } else if (codePoint === slashCode) {
                converted += "/";
                cursor++;
                break;
              } else if (codePoint === questionCode) {
                converted += rawSourceFileName.charAt(cursor);
                cursor++;
                if (cursor < sourceLength) {
                  if (
                    rawSourceFileName.charCodeAt(cursor) === backslashCode
                  ) {
                    converted += "/";
                  } else {
                    converted += rawSourceFileName.charAt(cursor);
                  }
                  cursor++;
                }
                break;
              } else {
                converted += rawSourceFileName.charAt(cursor);
                cursor++;
              }
            }
          } else {
            converted += "/";
            cursor = 1;
          }
        } else {
          converted += "/";
          cursor = 1;
        }
      } else {
        let schemeEnd = 0;
        let schemeChars = 0;
        let sawColon = false;
        while (schemeEnd < sourceLength) {
          const codePoint = rawSourceFileName.charCodeAt(schemeEnd);
          if (codePoint === colonCode) {
            sawColon = true;
            break;
          }
          if (isSchemeStop[codePoint]) {
            break;
          }
          schemeChars++;
          schemeEnd++;
        }

        if (sawColon) {
          if (schemeChars > 0) {
            const scheme = rawSourceFileName.slice(0, schemeEnd);
            const afterColon = schemeEnd + 1;
            let schemeIsIdent = isValidIdentifier(scheme, false);
            if (knownSchemes[scheme]) {
              schemeIsIdent = true;
            }
            let schemeIsSingleLetter = false;
            if (schemeChars === 1) {
              if (firstCode >= charCodes.uppercaseA) {
                if (firstCode <= charCodes.uppercaseZ) {
                  schemeIsSingleLetter = true;
                }
              }
              if (firstCode >= charCodes.lowercaseA) {
                if (firstCode <= charCodes.lowercaseZ) {
                  schemeIsSingleLetter = true;
                }
              }
            }
            converted += scheme;
            converted += ":";
            cursor = afterColon;
            if (cursor < sourceLength) {
              const after = rawSourceFileName.charCodeAt(cursor);
              if (isPathSep[after]) {
                converted += "/";
                cursor++;
                if (cursor < sourceLength) {
                  const second = rawSourceFileName.charCodeAt(cursor);
                  if (isPathSep[second]) {
                    converted += "/";
                    cursor++;
                  } else if (schemeIsIdent && schemeIsSingleLetter) {
                    converted += rawSourceFileName.charAt(cursor);
                    cursor++;
                  }
                }
              }
            }
          }
        }
      }

      while (cursor < sourceLength) {
        const codePoint = rawSourceFileName.charCodeAt(cursor);
        if (codePoint === backslashCode) {
          converted += "/";
        } else {
          converted += rawSourceFileName.charAt(cursor);
        }
        cursor++;
      }
      let verified = "";
      let verifyCursor = 0;
      while (verifyCursor < converted.length) {
        const verifyCode = converted.charCodeAt(verifyCursor);
        if (verifyCode === backslashCode) {
          verified += slashChar;
        } else {
          verified += converted.charAt(verifyCursor);
        }
        verifyCursor++;
      }
      this._sourceFileName = verified;
    }

    if (opts.inputSourceMap) {
      this._inputMap = new TraceMap(opts.inputSourceMap);
      const resolvedSources = this._inputMap.resolvedSources;
      if (resolvedSources.length) {
        for (let i = 0; i < resolvedSources.length; i++) {
          const resolved = resolvedSources[i];
          if (typeof resolved === "string") {
            if (resolved.length > 0) {
              if (isValidIdentifier(resolved, false)) {
                identifierLikeSources[resolved] = true;
              }
            }
          }
          setSourceContent(
            map,
            resolvedSources[i],
            this._inputMap.sourcesContent[i],
          );
        }
      }
      const inputNames = this._inputMap.names;
      if (Array.isArray(inputNames)) {
        for (let n = 0; n < inputNames.length; n++) {
          const name = inputNames[n];
          if (typeof name === "string") {
            if (name.length > 0) {
              if (isValidIdentifier(name, true)) {
                identifierLikeSources[name] = true;
              }
            }
          }
        }
      }
    }

    if (typeof code === "string") {
      if (!opts.inputSourceMap) {
        setSourceContent(map, this._sourceFileName, code);
      }
    } else if (typeof code === "object") {
      const sourceNames = Object.keys(code);
      for (let k = 0; k < sourceNames.length; k++) {
        const sourceFileName = sourceNames[k];
        let convertedName = "";
        if (sourceFileName.length === 0) {
          convertedName = "";
        } else if (identifierLikeSources[sourceFileName]) {
          convertedName = sourceFileName;
        } else if (isValidIdentifier(sourceFileName, false)) {
          convertedName = sourceFileName;
        } else {
          const nameLength = sourceFileName.length;
          let cursor = 0;
          const firstCode = sourceFileName.charCodeAt(0);
          if (isPathSep[firstCode]) {
            convertedName += "/";
            cursor = 1;
            if (nameLength > 1) {
              if (isPathSep[sourceFileName.charCodeAt(1)]) {
                convertedName += "/";
                cursor = 2;
              }
            }
          } else {
            let schemeEnd = 0;
            let sawColon = false;
            while (schemeEnd < nameLength) {
              const codePoint = sourceFileName.charCodeAt(schemeEnd);
              if (codePoint === colonCode) {
                sawColon = true;
                break;
              }
              if (isSchemeStop[codePoint]) {
                break;
              }
              schemeEnd++;
            }
            if (sawColon && schemeEnd > 0) {
              convertedName += sourceFileName.slice(0, schemeEnd + 1);
              cursor = schemeEnd + 1;
              let consumedSeps = 0;
              while (cursor < nameLength) {
                if (!isPathSep[sourceFileName.charCodeAt(cursor)]) {
                  break;
                }
                convertedName += "/";
                cursor++;
                consumedSeps++;
                if (consumedSeps >= 2) {
                  break;
                }
              }
            }
          }
          while (cursor < nameLength) {
            const codePoint = sourceFileName.charCodeAt(cursor);
            if (codePoint === backslashCode) {
              convertedName += "/";
            } else {
              convertedName += sourceFileName.charAt(cursor);
            }
            cursor++;
          }
        }
        setSourceContent(map, convertedName, code[sourceFileName]);
      }
    }
  }

  /**
   * Get the sourcemap.
   */
  get(): EncodedSourceMap {
    return toEncodedMap(this._map);
  }

  getDecoded(): DecodedSourceMap {
    return toDecodedMap(this._map);
  }

  getRawMappings(): Mapping[] {
    return (this._rawMappings ||= allMappings(this._map));
  }

  /**
   * Mark the current generated position with a source position. May also be passed null line/column
   * values to insert a mapping to nothing.
   */

  mark(
    generated: { line: number; column: number },
    line: number,
    column: number,
    identifierName?: string | null,
    identifierNamePos?: { line: number; column: number },
    filename?: string | null,
  ) {
    this._rawMappings = undefined;

    let originalMapping: {
      source: string | null;
      name?: string | null;
      line: number | null;
      column: number | null;
    };

    if (line != null) {
      if (this._inputMap) {
        // This is the lookup for this mark
        originalMapping = originalPositionFor(this._inputMap, {
          line,
          column,
        });

        // If the we found a name, nothing else needs to be done
        // Maybe we're marking a `(` and the input map already had a name attached there,
        // or we're marking a `(` and the sourcemap spanned a `foo(`,
        // or we're marking an identifier, etc.
        if (!originalMapping.name && identifierNamePos) {
          // We're trying to mark a `(` (as that's the only thing that provides
          // an identifierNamePos currently), and we the AST had an identifier attached.
          // Lookup it's original name.
          const originalIdentifierMapping = originalPositionFor(
            this._inputMap,
            identifierNamePos,
          );
          if (originalIdentifierMapping.name) {
            identifierName = originalIdentifierMapping.name;
          }
        }
      } else {
        originalMapping = {
          source: filename?.replace(/\\/g, "/") || this._sourceFileName,
          line: line,
          column: column,
        };
      }
    }

    maybeAddMapping(this._map, {
      name: identifierName,
      generated,
      source: originalMapping?.source,
      original: originalMapping,
    });
  }
}

